import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONT LOADER
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type AIBrowserMorphProps = Record<string, any>;

// ------------------------------------------------------------------
// SUB-COMPONENTS
// ------------------------------------------------------------------

// 1. Data Background (Subtle flowing lines)
const DataBackground = ({
  color,
  opacity,
}: {
  color: string;
  opacity: number;
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Generate deterministic lines
  const lines = useMemo(() => {
    return new Array(8).fill(0).map((_, i) => ({
      x: (width / 8) * i + (width / 16),
      speed: 0.5 + Math.abs(random(i) * 1.5),
      height: 200 + Math.abs(random(i + 10) * 400),
      offset: random(i + 20) * height,
    }));
  }, [width, height]);

  return (
    <AbsoluteFill style={{ overflow: "hidden", zIndex: 0 }}>
      {lines.map((line, i) => {
        const yPos = (frame * line.speed + line.offset) % (height + line.height);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: line.x,
              top: yPos - line.height,
              width: 1,
              height: line.height,
              background: `linear-gradient(to bottom, transparent, ${color}, transparent)`,
              opacity: opacity,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

// 2. Icons
const SearchIcon = ({ color }: { color: string }) => (
  <svg
    width="20"
    height="20"
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth="2.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <circle cx="11" cy="11" r="8" />
    <line x1="21" y1="21" x2="16.65" y2="16.65" />
  </svg>
);

const SparklesIcon = ({ color }: { color: string }) => (
  <svg
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M12 2L14.4 7.2L20 9L14.4 10.8L12 16L9.6 10.8L4 9L9.6 7.2L12 2Z" />
  </svg>
);

// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------
const AIBrowserMorph: React.FC<AIBrowserMorphProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  accentColor = "#10a37f",
  messageText = "Did you know AI is brand dialogue for math, models and data?",
  finalText = "We scaled math until it looked like thinking.",
  durationInSeconds = 10,
}) => {
  useFontLoader(["Inter"]);
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Safe color parsing
  const bg = transparentBackground ? "transparent" : backgroundColor;

  // ----------------------------------------------------------------
  // TIMING CONFIGURATION (Frames)
  // ----------------------------------------------------------------
  const startDelay = 10;
  const bubbleEnterDuration = 25;
  const tapStart = startDelay + bubbleEnterDuration + 20; // ~55
  const tapDuration = 10;
  const morphStart = tapStart + tapDuration + 5; // ~70
  const morphDuration = 25;
  const typeStart = morphStart + morphDuration + 10; // ~105
  const typeDuration = 40;
  const loadStart = typeStart + typeDuration + 10; // ~155
  const loadDuration = 20;
  const answerStart = loadStart + loadDuration + 10; // ~185
  const finalStart = answerStart + 40; // ~225

  // ----------------------------------------------------------------
  // ANIMATION CALCULATIONS
  // ----------------------------------------------------------------

  // 1. Bubble Entrance (Spring)
  const bubbleSpring = spring({
    frame: frame - startDelay,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // 2. Tap Interaction
  const tapProgress = interpolate(
    frame,
    [tapStart, tapStart + tapDuration / 2, tapStart + tapDuration],
    [1, 0.95, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Morph Progress (0 -> 1)
  const morphProgress = interpolate(
    frame,
    [morphStart, morphStart + morphDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.25, 1, 0.5, 1) }
  );

  // Morph Values
  // Initial Bubble State
  const bubbleWidth = width * 0.85;
  const bubbleHeight = 120; // Approximate
  const bubbleY = height * 0.5; // Center
  const bubbleRadius = 24;

  // Final Browser State
  const browserWidth = width * 0.92;
  const browserHeight = height * 0.6;
  const browserY = height * 0.15; // Top area
  const browserRadius = 16;

  const currentWidth = interpolate(morphProgress, [0, 1], [bubbleWidth, browserWidth]);
  const currentHeight = interpolate(morphProgress, [0, 1], [bubbleHeight, browserHeight]);
  const currentY = interpolate(morphProgress, [0, 1], [bubbleY, browserY]);
  const currentRadius = interpolate(morphProgress, [0, 1], [bubbleRadius, browserRadius]);
  const currentBg = interpolate(morphProgress, [0, 1], [0, 1]); // 0 = Accent, 1 = White

  // Background Color transition for the box: Accent -> White
  // We handle this via opacity overlapping to avoid color interpolation complexities with zColor
  // But CSS transition is forbidden, so we use absolute overlay.

  // 4. Content Opacities
  const bubbleContentOpacity = interpolate(morphProgress, [0, 0.3], [1, 0]);
  const browserChromeOpacity = interpolate(morphProgress, [0.7, 1], [0, 1]);

  // 5. Typing Animation
  const typingProgress = interpolate(
    frame,
    [typeStart, typeStart + typeDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const charsToShow = Math.round(typingProgress * messageText.length);
  const displayedQuery = messageText.slice(0, charsToShow);

  // 6. Loading Bar
  const loadingProgress = interpolate(
    frame,
    [loadStart, loadStart + loadDuration],
    [0, 100],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.ease) }
  );
  const loadingOpacity = interpolate(
    frame,
    [loadStart, loadStart + 5, loadStart + loadDuration, loadStart + loadDuration + 10],
    [0, 1, 1, 0],
    { extrapolateRight: "clamp" }
  );

  // 7. Answer Card
  const answerOpacity = interpolate(
    frame,
    [answerStart, answerStart + 20],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const answerSlide = interpolate(
    frame,
    [answerStart, answerStart + 20],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)) }
  );

  // 8. Final Text
  const finalOpacity = interpolate(
    frame,
    [finalStart, finalStart + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // ----------------------------------------------------------------
  // RENDER
  // ----------------------------------------------------------------
  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        fontFamily: "Inter, sans-serif",
        color: "#111",
      }}
    >
      {/* Background Data Lines */}
      <DataBackground color={accentColor} opacity={0.15} />

      {/* Main Interactive Element (Morphing Box) */}
      <div
        style={{
          position: "absolute",
          left: (width - currentWidth) / 2,
          top: currentY,
          width: currentWidth,
          height: currentHeight,
          borderRadius: currentRadius,
          backgroundColor: "#fff",
          boxShadow: "0 20px 60px -10px rgba(0,0,0,0.15)",
          overflow: "hidden",
          transform: `scale(${tapProgress})`,
          // For initial bubble slide-up
          opacity: bubbleSpring,
          transformOrigin: "center center",
          // Apply slide up only when strictly in bubble mode
          marginTop: interpolate(bubbleSpring, [0, 1], [100, 0]) * (1 - morphProgress),
        }}
      >
        {/* State 1: Message Bubble Background (Accent Color) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: accentColor,
            opacity: 1 - currentBg, // Fades out as morph happens
          }}
        />

        {/* State 1: Message Content */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            padding: 24,
            display: "flex",
            alignItems: "center",
            opacity: bubbleContentOpacity,
          }}
        >
          <p
            style={{
              margin: 0,
              color: "#fff",
              fontSize: 28,
              fontWeight: 500,
              lineHeight: 1.4,
            }}
          >
            {messageText}
          </p>
        </div>

        {/* State 2: Browser Content */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            opacity: browserChromeOpacity,
            display: "flex",
            flexDirection: "column",
          }}
        >
          {/* Browser Header / Search Bar */}
          <div
            style={{
              padding: "24px 20px",
              borderBottom: "1px solid #eee",
              backgroundColor: "#fff",
            }}
          >
            <div
              style={{
                backgroundColor: "#f5f5f5",
                borderRadius: 12,
                padding: "16px 16px",
                display: "flex",
                alignItems: "center",
                gap: 12,
              }}
            >
              <SearchIcon color="#888" />
              <div
                style={{
                  fontSize: 22,
                  color: "#333",
                  fontWeight: 500,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  width: "100%",
                  position: "relative",
                }}
              >
                {displayedQuery}
                {/* Cursor */}
                {frame > typeStart && frame < typeStart + typeDuration + 10 && (
                  <span
                    style={{
                      display: "inline-block",
                      width: 2,
                      height: 24,
                      backgroundColor: accentColor,
                      marginLeft: 2,
                      verticalAlign: "bottom",
                      opacity: Math.sin(frame * 0.5) > 0 ? 1 : 0,
                    }}
                  />
                )}
              </div>
            </div>
            {/* Loading Bar */}
            <div
              style={{
                height: 3,
                width: "100%",
                marginTop: 16,
                backgroundColor: "#eee",
                borderRadius: 2,
                overflow: "hidden",
                opacity: loadingOpacity,
              }}
            >
              <div
                style={{
                  height: "100%",
                  width: `${loadingProgress}%`,
                  backgroundColor: accentColor,
                }}
              />
            </div>
          </div>

          {/* Browser Body / Result */}
          <div
            style={{
              flex: 1,
              padding: 24,
              backgroundColor: "#f9f9f9",
              position: "relative",
            }}
          >
            <div
              style={{
                backgroundColor: "#fff",
                borderRadius: 16,
                padding: 24,
                boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
                opacity: answerOpacity,
                transform: `translateY(${answerSlide}px)`,
                border: "1px solid rgba(0,0,0,0.05)",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
                <div
                  style={{
                    width: 32,
                    height: 32,
                    borderRadius: "50%",
                    backgroundColor: accentColor,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <SparklesIcon color="#fff" />
                </div>
                <span style={{ fontWeight: 700, fontSize: 18, color: "#333" }}>AI Answer</span>
              </div>
              <p
                style={{
                  fontSize: 20,
                  lineHeight: 1.5,
                  color: "#444",
                  margin: 0,
                }}
              >
                By modeling the statistical patterns of language, we transformed raw data into fluent dialogue. It's not just math; it's the geometry of thought.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Final Text Overlay */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.15,
          left: width * 0.1,
          width: width * 0.8,
          textAlign: "center",
          opacity: finalOpacity,
          transform: `translateY(${interpolate(finalOpacity, [0, 1], [20, 0])}px)`,
        }}
      >
        <h2
          style={{
            fontSize: 36,
            fontWeight: 600,
            color: "#111",
            margin: 0,
            letterSpacing: -0.5,
          }}
        >
          {finalText}
        </h2>
      </div>
    </AbsoluteFill>
  );
};

export default AIBrowserMorph;